const state = { token: sessionStorage.getItem('rinova-admin-token') || '', products: [], orders: [], settings: {}, days: 30, posProducts: [], posCart: [], barcodeLabels: [], adminChat: [], adminMode: sessionStorage.getItem('rinova-admin-mode') === 'edit' ? 'edit' : 'view' };
const $ = (selector) => document.querySelector(selector);
const money = (value) => `৳${Number(value || 0).toLocaleString('en-BD')}`;
const escapeHtml = (value) => String(value ?? '').replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#039;' }[char]));
const optionalNumber = (value) => value === '' ? null : Number(value);
function toast(message) { const node = $('#toast'); node.textContent = message; node.classList.add('show'); setTimeout(() => node.classList.remove('show'), 2400); }
function parseEditorMedia(value) { const raw = String(value || '').trim(); if (!raw) return []; const parsed = JSON.parse(raw); if (!Array.isArray(parsed)) throw new Error('Media must be a JSON array.'); return parsed.map((item) => { const entry = typeof item === 'string' ? { type: 'image', url: item } : item; const url = String(entry?.url || '').trim(); if (!/^(https:\/\/|\/assets\/)/i.test(url)) throw new Error('Media URLs must start with https:// or /assets/.'); return { type: entry?.type === 'video' ? 'video' : 'image', url, ...(entry?.alt ? { alt: String(entry.alt).slice(0, 160) } : {}) }; }); }
function renderMediaPreview() { const form = $('#product-form'); const preview = $('#media-preview'); if (!form || !preview) return; try { const primary = String(form.elements.namedItem('imageUrl')?.value || '').trim(); const media = [...(primary ? [{ type: 'image', url: primary }] : []), ...parseEditorMedia(form.elements.namedItem('mediaJson')?.value || '')]; preview.innerHTML = media.filter((item) => /^(https:\/\/|\/assets\/)/i.test(item.url)).map((item) => item.type === 'video' ? `<span class="media-preview-item media-preview-video">▶ Video</span>` : `<img class="media-preview-item" src="${escapeHtml(item.url)}" alt="" />`).join(''); } catch (error) { preview.innerHTML = `<span class="form-message">${escapeHtml(error.message)}</span>`; } }
function updateImagePreview() { const input = document.querySelector('#product-form [name="imageUrl"]'); const preview = $('#image-preview'); const url = input?.value?.trim() || ''; if (!url) { preview.classList.add('hidden'); preview.removeAttribute('src'); } else { preview.src = url; preview.classList.remove('hidden'); preview.onerror = () => preview.classList.add('hidden'); } renderMediaPreview(); }
function setAdminMode(mode) { state.adminMode = mode === 'edit' ? 'edit' : 'view'; sessionStorage.setItem('rinova-admin-mode', state.adminMode); document.body.dataset.adminMode = state.adminMode; document.querySelectorAll('[data-admin-mode]').forEach((button) => button.classList.toggle('active', button.dataset.adminMode === state.adminMode)); const hint = $('#mode-hint'); if (hint) hint.textContent = state.adminMode === 'edit' ? 'Edit Mode: live changes are enabled.' : 'View Mode: inspect the live shop, then choose Quick edit when needed.'; if (state.products.length) renderProducts(); }
const morningTasks = [{ id: 'overview', label: 'Dashboard numbers', detail: 'Revenue, orders, stock এবং restock দেখুন।', view: 'overview' }, { id: 'orders', label: 'Pending orders', detail: 'নতুন order, payment এবং customer তথ্য মিলান।', view: 'orders' }, { id: 'inventory', label: 'Low stock', detail: 'যে product threshold-এর নিচে আছে তা দেখুন।', view: 'inventory' }, { id: 'returns', label: 'Return requests', detail: 'নতুন return request approve বা review করুন।', view: 'returns' }, { id: 'pos', label: 'Yesterday POS', detail: 'গতকালের দোকানের sale ও receipt record দেখুন।', view: 'pos' }, { id: 'storefront', label: 'Live storefront', detail: 'দাম, image, stock এবং visible product একবার দেখুন।', href: '/?admin_preview=1' }];
function morningStorageKey() { return `rinova-morning-check-${new Date().toISOString().slice(0, 10)}`; }
function morningChecked() { try { return JSON.parse(localStorage.getItem(morningStorageKey()) || '{}'); } catch { return {}; } }
function renderMorningChecklist() { const node = $('#morning-checklist-list'); if (!node) return; const checked = morningChecked(); node.innerHTML = morningTasks.map((task) => `<div class="morning-check-item ${checked[task.id] ? 'done' : ''}"><button class="morning-check-toggle" type="button" data-morning-toggle="${task.id}" aria-label="${checked[task.id] ? 'Uncheck' : 'Complete'} ${escapeHtml(task.label)}">${checked[task.id] ? '✓' : ''}</button><span class="morning-check-copy"><strong>${escapeHtml(task.label)}</strong><small>${escapeHtml(task.detail)}</small></span>${task.href ? `<a class="icon-action morning-open" href="${task.href}" target="${task.id === 'storefront' ? '_self' : '_blank'}" rel="noopener">Open</a>` : `<button class="icon-action morning-open" type="button" data-morning-view="${task.view}">Open</button>`}</div>`).join(''); }
function toggleMorningTask(id) { const checked = morningChecked(); checked[id] = !checked[id]; localStorage.setItem(morningStorageKey(), JSON.stringify(checked)); renderMorningChecklist(); }
async function api(path, options = {}) { const headers = { 'Content-Type': 'application/json', ...(options.headers || {}) }; if (state.token) headers.Authorization = `Bearer ${state.token}`; const response = await fetch(`/api${path}`, { ...options, headers }); const data = await response.json().catch(() => ({})); if (!response.ok) throw new Error(data.error || 'Request failed'); return data; }
async function uploadProductImage(file) { const headers = {}; if (state.token) headers.Authorization = `Bearer ${state.token}`; const form = new FormData(); form.append('file', file); const response = await fetch('/api/admin/product-media', { method: 'POST', headers, body: form }); const data = await response.json().catch(() => ({})); if (!response.ok) throw new Error(data.error || 'Image upload failed.'); return data.media; }
async function uploadPrimaryImage() { const input = $('#primary-image-file'); const file = input?.files?.[0]; if (!file) return toast('Choose a primary image first.'); const message = $('#upload-message'); message.textContent = 'Uploading primary image…'; try { const media = await uploadProductImage(file); const field = $('#product-form').elements.namedItem('imageUrl'); field.value = media.url; updateImagePreview(); message.textContent = 'Primary image uploaded. Save the product to apply it.'; input.value = ''; } catch (error) { message.textContent = error.message; } }
async function uploadGalleryImages() { const input = $('#gallery-image-files'); const files = Array.from(input?.files || []); if (!files.length) return toast('Choose one or more gallery images first.'); const message = $('#upload-message'); message.textContent = `Uploading ${files.length} image${files.length === 1 ? '' : 's'}…`; try { const uploaded = await Promise.all(files.map(uploadProductImage)); const field = $('#product-form').elements.namedItem('mediaJson'); const existing = parseEditorMedia(field.value || ''); field.value = JSON.stringify([...existing, ...uploaded], null, 2); renderMediaPreview(); message.textContent = `${uploaded.length} gallery image${uploaded.length === 1 ? '' : 's'} uploaded. Save the product to apply them.`; input.value = ''; } catch (error) { message.textContent = error.message; } }
function showApp(username) { $('#login-screen').classList.add('hidden'); $('#app-shell').classList.remove('hidden'); $('#signed-in-user').textContent = username || 'Admin'; setAdminMode(state.adminMode); renderMorningChecklist(); const params = new URLSearchParams(window.location.search); const allowedViews = ['overview', 'products', 'orders', 'inventory', 'settings', 'returns', 'reviews', 'pos', 'cms', 'assistant']; const requestedView = allowedViews.includes(params.get('view')) ? params.get('view') : 'overview'; loadView(requestedView); const editId = Number(params.get('edit') || 0); if (requestedView === 'products' && editId) setTimeout(() => { const product = state.products.find((item) => Number(item.id) === editId); if (product) openProductEditor(product); }, 300); }
function showLogin() { $('#login-screen').classList.remove('hidden'); $('#app-shell').classList.add('hidden'); }
async function login(event) { event.preventDefault(); $('#login-error').textContent = ''; try { const data = await api('/admin/login', { method: 'POST', body: JSON.stringify({ username: $('#login-username').value, password: $('#login-password').value }) }); state.token = data.token; sessionStorage.setItem('rinova-admin-token', state.token); showApp(data.username); } catch (error) { $('#login-error').textContent = error.message; } }
async function boot() { if (!state.token) return showLogin(); try { const session = await api('/admin/session'); showApp(session.username); } catch { sessionStorage.removeItem('rinova-admin-token'); state.token = ''; showLogin(); } }
function closeMobileNav() { const sidebar = $('.sidebar'); const backdrop = $('#sidebar-backdrop'); sidebar?.classList.remove('open'); backdrop?.classList.remove('open'); backdrop?.setAttribute('aria-hidden', 'true'); $('#mobile-menu')?.setAttribute('aria-expanded', 'false'); document.body.classList.remove('nav-open'); }
function toggleMobileNav(open) { const sidebar = $('.sidebar'); const backdrop = $('#sidebar-backdrop'); sidebar?.classList.toggle('open', open); backdrop?.classList.toggle('open', open); backdrop?.setAttribute('aria-hidden', String(!open)); $('#mobile-menu')?.setAttribute('aria-expanded', String(open)); document.body.classList.toggle('nav-open', open); }
function loadView(view) { $('#view-assistant')?.classList.remove('assistant-popover'); document.body.classList.remove('assistant-open'); closeMobileNav(); document.querySelectorAll('.view').forEach((node) => node.classList.toggle('hidden', node.id !== `view-${view}`)); document.querySelectorAll('.nav-item[data-view]').forEach((node) => node.classList.toggle('active', node.dataset.view === view)); $('#view-title').textContent = ({ overview: 'Dashboard', products: 'Products', orders: 'Orders', inventory: 'Inventory', settings: 'Settings', returns: 'Returns', reviews: 'Reviews', pos: 'POS & Barcodes', cms: 'Content CMS', assistant: 'Admin Assistant' })[view] || 'Dashboard'; if (view === 'overview') loadOverview(); if (view === 'products' || view === 'inventory') loadProducts(); if (view === 'orders') loadOrders(); if (view === 'settings') loadSettings(); if (view === 'returns') loadReturns(); if (view === 'reviews') loadReviews(); if (view === 'pos') loadPosProducts(); if (view === 'cms') loadCms(); if (view === 'assistant') renderAdminChat(); }
function openAssistantPopup() { loadView('assistant'); const assistant = $('#view-assistant'); assistant.classList.add('assistant-popover'); document.body.classList.add('assistant-open'); $('#admin-chat-input')?.focus(); }
async function loadOverview() { try { const data = await api(`/admin/overview?days=${state.days}`); const s = data.stock || {}; $('#metric-grid').innerHTML = [['Revenue', money(data.revenue?.revenue)], ['Gross profit', money(data.grossProfit)], ['Orders', Number(data.revenue?.orders || 0).toLocaleString('en-BD')], ['Avg order value', money(data.revenue?.orders ? data.revenue.revenue / data.revenue.orders : 0)], ['Stock on hand', Number(s.units || 0).toLocaleString('en-BD')], ['Stock at cost', money(s.costValue)], ['Unrealised profit', money((s.retailValue || 0) - (s.costValue || 0))], ['Needs restocking', Number(s.needsRestock || 0).toLocaleString('en-BD')]].map(([label, value]) => `<article class="metric"><div class="metric-label">${label}</div><div class="metric-value">${value}</div></article>`).join(''); const max = Math.max(...(data.pipeline || []).map((item) => Number(item.orders)), 1); $('#pipeline').innerHTML = (data.pipeline || []).length ? data.pipeline.map((item) => `<div class="pipeline-row"><span>${escapeHtml(item.status)}</span><div class="bar"><i style="width:${Math.round(Number(item.orders) / max * 100)}%"></i></div><strong>${item.orders}</strong></div>`).join('') : '<p class="muted">No orders in this period.</p>'; $('#top-products').innerHTML = (data.topProducts || []).length ? data.topProducts.map((item) => `<div class="list-row"><span><strong>${escapeHtml(item.productName)}</strong><small>${item.units} units</small></span><strong>${money(item.revenue)}</strong></div>`).join('') : '<p class="muted">No product sales in this period.</p>'; } catch (error) { toast(error.message); } }
async function loadProducts() { try { const data = await api(`/admin/products?q=${encodeURIComponent($('#product-search')?.value || '')}&status=${encodeURIComponent($('#product-status')?.value || '')}`); state.products = data.products || []; renderProducts(); } catch (error) { toast(error.message); } }
function margin(product) { return Number(product.price) ? Math.round((Number(product.price) - Number(product.costPrice || 0)) / Number(product.price) * 100) : 0; }
function renderProducts() { const rows = state.products.map((product) => { const actions = state.adminMode === 'edit' ? `<button class="icon-action" data-edit-id="${product.id}">Edit</button> <button class="icon-action" data-stock-id="${product.id}" data-stock-name="${escapeHtml(product.name)}">Stock</button>` : `<a class="icon-action" href="/products/${encodeURIComponent(product.slug)}?admin_preview=1">View live</a> <button class="icon-action" data-quick-edit-id="${product.id}">Quick edit</button>`; return `<tr><td><strong>${escapeHtml(product.name)}</strong><small>${escapeHtml(product.categoryName || 'Uncategorised')}</small></td><td>${escapeHtml(product.sku)}</td><td>${money(product.price)}</td><td>${money(product.costPrice)}</td><td>${margin(product)}%</td><td><strong>${product.stock}</strong><small>threshold ${product.lowStockThreshold}</small></td><td><span class="status-pill ${escapeHtml(product.status)}">${escapeHtml(product.status)}</span></td><td>${actions}</td></tr>`; }).join(''); $('#products-table').innerHTML = rows || '<tr><td colspan="8" class="muted">No products found.</td></tr>'; $('#inventory-table').innerHTML = state.products.map((product) => `<tr><td><strong>${escapeHtml(product.name)}</strong><small>${escapeHtml(product.sku)}</small></td><td><strong>${product.stock}</strong></td><td>${product.lowStockThreshold}</td><td>${money(product.stock * (product.costPrice || 0))}</td><td>${state.adminMode === 'edit' ? `<button class="icon-action" data-stock-id="${product.id}" data-stock-name="${escapeHtml(product.name)}">Adjust stock</button>` : '<span class="muted">View only</span>'}</td></tr>`).join('') || '<tr><td colspan="5" class="muted">No products found.</td></tr>'; }
async function loadOrders() { try { const data = await api(`/admin/orders?q=${encodeURIComponent($('#order-search')?.value || '')}&status=${encodeURIComponent($('#order-status')?.value || '')}`); state.orders = data.orders || []; const statuses = ['pending','confirmed','processing','shipped','delivered','returned','customer_cancelled','admin_cancelled']; $('#orders-table').innerHTML = state.orders.map((order) => `<tr><td><strong>${escapeHtml(order.orderCode)}</strong><small>${escapeHtml(order.createdAt)}</small></td><td><strong>${escapeHtml(order.name)}</strong><small>${escapeHtml(order.phone)}</small></td><td>${money(Number(order.subtotal) + Number(order.deliveryFee))}</td><td>${escapeHtml(order.paymentMethod)}<small>${escapeHtml(order.paymentStatus)}</small></td><td>${escapeHtml(order.courierStatus || 'not booked')}</td><td><select class="order-status-select" data-order-code="${escapeHtml(order.orderCode)}">${statuses.map((status) => `<option value="${status}" ${status === order.status ? 'selected' : ''}>${status}</option>`).join('')}</select></td><td>${escapeHtml(order.district || '')}<br><button class="icon-action" data-print-order="${escapeHtml(order.orderCode)}">Print invoice</button></td></tr>`).join('') || '<tr><td colspan="7" class="muted">No orders found.</td></tr>'; } catch (error) { toast(error.message); } }
async function loadSettings() { try { const data = await api('/admin/settings'); state.settings = data.settings || {}; const labels = { store_name: 'Store name', tagline: 'Tagline', support_phone: 'Support phone', support_email: 'Support email', currency_code: 'Currency code', currency_symbol: 'Currency symbol', delivery_inside_dhaka: 'Delivery inside Dhaka', delivery_outside_dhaka: 'Delivery outside Dhaka', free_delivery_over: 'Free delivery over', order_whatsapp_number: 'Order WhatsApp number', bkash_number: 'bKash number', nagad_number: 'Nagad number', rocket_number: 'Rocket number', tax_percentage: 'Tax percentage', site_description: 'Site description', site_logo_url: 'Logo URL', favicon_url: 'Favicon URL' }; $('#settings-form').innerHTML = Object.entries(labels).map(([key, label]) => `<label class="setting-field">${label}<input name="${key}" value="${escapeHtml(state.settings[key] || '')}" /></label>`).join('') + '<div class="setting-actions"><button class="button button-dark" type="submit">Save settings <span>→</span></button><span id="settings-message" class="form-message"></span></div>'; } catch (error) { toast(error.message); } }
function parseProductBadges(value) { let parsed = []; try { parsed = Array.isArray(value) ? value : JSON.parse(value || '[]'); } catch {} return Array.isArray(parsed) ? parsed.map((item) => String(item).toLowerCase()).filter((item) => ['hot', 'instock', 'new'].includes(item)) : []; }
function openProductEditor(product) { setAdminMode('edit'); const form = $('#product-form'); form.reset(); form.dataset.id = product?.id || ''; $('#editor-heading').textContent = product ? 'Edit product' : 'Create a product'; $('#product-submit').innerHTML = product ? 'Save changes <span>→</span>' : 'Create product <span>→</span>'; $('#product-form-message').textContent = ''; if ($('#upload-message')) $('#upload-message').textContent = ''; if (product) { for (const [key, value] of Object.entries({ name: product.name, sku: product.sku, brand: product.brand, categoryId: product.categoryId, shortDescription: product.shortDescription, description: product.description, editorNote: product.editorNote, costPrice: product.costPrice, price: product.price, compareAtPrice: product.compareAtPrice, stock: product.stock, lowStockThreshold: product.lowStockThreshold, minOrderQty: product.minOrderQty, volumeTiers: product.volumeTiersJson || '[]', weightGrams: product.weightGrams, barcode: product.barcode, imageUrl: product.imageUrl, mediaJson: product.mediaJson || '[]', status: product.status })) { const field = form.elements.namedItem(key); if (field) field.value = value ?? ''; } form.elements.namedItem('featured').checked = Boolean(product.featured); const badges = parseProductBadges(product.badgesJson || product.badges); form.elements.namedItem('badgeHot').checked = badges.includes('hot'); form.elements.namedItem('badgeInstock').checked = badges.includes('instock'); form.elements.namedItem('badgeNew').checked = badges.includes('new'); } else { form.elements.namedItem('badgeHot').checked = false; form.elements.namedItem('badgeInstock').checked = false; form.elements.namedItem('badgeNew').checked = false; } updateImagePreview(); $('#product-editor').classList.remove('hidden'); window.scrollTo({ top: 0, behavior: 'smooth' }); }
async function saveProduct(event) { event.preventDefault(); const form = event.target; const data = Object.fromEntries(new FormData(form).entries()); data.featured = form.elements.namedItem('featured').checked; data.badges = ['hot', 'instock', 'new'].filter((badge) => form.elements.namedItem(`badge${badge === 'hot' ? 'Hot' : badge === 'instock' ? 'Instock' : 'New'}`).checked); data.volumeTiers = data.volumeTiers || '[]'; try { data.mediaJson = JSON.stringify(parseEditorMedia(data.mediaJson)); } catch (error) { $('#product-form-message').textContent = error.message; return; } for (const key of ['categoryId','costPrice','price','stock','lowStockThreshold','minOrderQty','weightGrams']) data[key] = Number(data[key] || 0); data.compareAtPrice = optionalNumber(data.compareAtPrice); const id = form.dataset.id; try { if (id) await api(`/admin/products/${id}`, { method: 'PATCH', body: JSON.stringify(data) }); else await api('/admin/products', { method: 'POST', body: JSON.stringify(data) }); $('#product-form-message').textContent = id ? 'Product updated successfully.' : 'Product created successfully.'; toast(id ? 'Product updated' : 'Product created'); await loadProducts(); } catch (error) { $('#product-form-message').textContent = error.message; } }
async function adjustStock(id, name) { const quantity = window.prompt(`Stock change for ${name}. Use a positive or negative number:`); if (quantity === null) return; const reason = window.prompt('Reason: restock, return, damage, adjustment, sale or cancellation', 'adjustment'); if (reason === null) return; try { const data = await api(`/admin/products/${id}/stock`, { method: 'POST', body: JSON.stringify({ mode: 'delta', quantity: Number(quantity), reason, note: `Updated from dashboard for ${name}` }) }); toast(`Stock updated to ${data.stock}`); await loadProducts(); } catch (error) { toast(error.message); } }
async function updateOrderStatus(orderCode, status) { try { await api(`/orders/${encodeURIComponent(orderCode)}/status`, { method: 'PATCH', body: JSON.stringify({ status, reason: 'Updated from admin dashboard' }) }); toast(`${orderCode} marked ${status}`); await loadOrders(); } catch (error) { toast(error.message); await loadOrders(); } }
async function loadReturns() { try { const data = await api(`/admin/returns?status=${encodeURIComponent($('#return-status').value || '')}`); $('#returns-table').innerHTML = (data.returns || []).map((item) => `<tr><td><strong>${escapeHtml(item.returnCode)}</strong><small>${escapeHtml(item.createdAt)}</small></td><td>${escapeHtml(item.orderCode)}</td><td>${escapeHtml(item.name)}<small>${escapeHtml(item.phone)}</small></td><td>${escapeHtml(item.reason)}</td><td>${money(item.amount)}</td><td><select class="return-status-select" data-return-id="${item.id}">${['requested','approved','picked_up','received','refunded','rejected','cancelled'].map((status) => `<option ${status === item.status ? 'selected' : ''}>${status}</option>`).join('')}</select></td><td><button class="icon-action" data-print-order="${escapeHtml(item.orderCode)}">Invoice</button></td></tr>`).join('') || '<tr><td colspan="7" class="muted">No returns found.</td></tr>'; } catch (error) { toast(error.message); } }
async function updateReturn(id, status) { try { await api(`/admin/returns/${id}`, { method: 'PATCH', body: JSON.stringify({ status }) }); toast('Return updated'); await loadReturns(); } catch (error) { toast(error.message); } }
async function loadReviews() { try { const data = await api(`/admin/reviews?status=${encodeURIComponent($('#review-status')?.value || '')}`); $('#reviews-table').innerHTML = (data.reviews || []).map((review) => `<tr><td><strong>${escapeHtml(review.productName)}</strong><small>Verified purchase</small></td><td>${escapeHtml(review.reviewerName)}</td><td><strong class="review-stars">${'★'.repeat(Number(review.rating || 0))}${'☆'.repeat(5 - Number(review.rating || 0))}</strong><small>${review.rating}/5</small></td><td class="review-cell">${escapeHtml(review.reviewText)}</td><td>${escapeHtml(review.orderCode)}<small>${escapeHtml(review.invoiceNumber || 'No invoice number')}</small></td><td><select class="review-status-select" data-review-id="${review.id}">${['pending','approved','rejected'].map((status) => `<option value="${status}" ${status === review.status ? 'selected' : ''}>${status}</option>`).join('')}</select></td><td><button class="icon-action" data-review-approve="${review.id}">Approve</button></td></tr>`).join('') || '<tr><td colspan="7" class="muted">No reviews found.</td></tr>'; } catch (error) { toast(error.message); } }
async function updateReview(id, status) { try { await api(`/admin/reviews/${id}`, { method: 'PATCH', body: JSON.stringify({ status }) }); toast(`Review ${status}`); await loadReviews(); } catch (error) { toast(error.message); await loadReviews(); } }
async function loadPosProducts() { try { const data = await api(`/admin/pos/products?q=${encodeURIComponent($('#pos-search').value || '')}`); state.posProducts = data.products || []; $('#pos-products-table').innerHTML = state.posProducts.map((product) => `<tr><td><strong>${escapeHtml(product.name)}</strong><small>${escapeHtml(product.sku)}</small></td><td>${escapeHtml(product.barcode || 'No barcode')}</td><td>${money(product.price)}</td><td>${product.stock}</td><td><span class="pos-action-group"><button class="icon-action" data-pos-add="${product.id}">Add sale</button><button class="icon-action" data-label-add="${product.id}">Add label</button></span></td></tr>`).join('') || '<tr><td colspan="5" class="muted">No products found.</td></tr>'; renderPosCart(); renderBarcodeLabels(); } catch (error) { toast(error.message); } }
function barcodeValue(product) { return String(product.barcode || product.sku || `RNV-${product.id}`).trim(); }
function renderBarcodeLabels() { const list = $('#barcode-label-list'); const sheet = $('#barcode-print-sheet'); if (!list || !sheet) return; list.innerHTML = state.barcodeLabels.length ? state.barcodeLabels.map((item) => `<div class="barcode-label-row"><div><strong>${escapeHtml(item.product.name)}</strong><small>${escapeHtml(barcodeValue(item.product))} · ${money(item.product.price)}</small></div><label>Qty<input type="number" min="1" max="999" value="${item.quantity}" data-label-quantity="${item.product.id}" /></label><button class="icon-action" data-label-remove="${item.product.id}">Remove</button></div>`).join('') : '<p class="muted">এখনও কোনো label selected হয়নি। POS product list থেকে Add label চাপুন।</p>'; const copies = state.barcodeLabels.flatMap((item) => Array.from({ length: item.quantity }, () => item.product)); sheet.innerHTML = copies.map((product) => `<div class="barcode-label"><strong>${escapeHtml(product.name)}</strong><svg data-barcode="${escapeHtml(barcodeValue(product))}"></svg><small>${escapeHtml(barcodeValue(product))} · ${money(product.price)}</small></div>`).join(''); sheet.setAttribute('aria-hidden', 'true'); if (window.JsBarcode) sheet.querySelectorAll('svg[data-barcode]').forEach((svg) => { try { window.JsBarcode(svg, svg.dataset.barcode, { format: 'CODE128', displayValue: false, height: 42, width: 1.5, margin: 2 }); } catch {} }); }
function addBarcodeLabel(id) { const product = state.posProducts.find((item) => Number(item.id) === Number(id)) || state.products.find((item) => Number(item.id) === Number(id)); if (!product) return; const existing = state.barcodeLabels.find((item) => Number(item.product.id) === Number(id)); if (existing) existing.quantity = Math.min(999, existing.quantity + 1); else state.barcodeLabels.push({ product, quantity: 1 }); renderBarcodeLabels(); }
function updateBarcodeLabel(id, quantity) { const item = state.barcodeLabels.find((entry) => Number(entry.product.id) === Number(id)); if (!item) return; item.quantity = Math.max(1, Math.min(999, Number(quantity) || 1)); renderBarcodeLabels(); }
function printBarcodeLabels() { if (!state.barcodeLabels.length) return toast('Add at least one product label first.'); renderBarcodeLabels(); window.print(); }
function renderPosCart() { $('#pos-cart').innerHTML = state.posCart.length ? state.posCart.map((item) => `<div class="list-row"><span><strong>${escapeHtml(item.product.name)}</strong><small>${item.quantity} × ${money(item.product.price)}</small></span><button class="icon-action" data-pos-remove="${item.product.id}">Remove</button></div>`).join('') : '<p class="muted">Scan a barcode or add a product to begin.</p>'; const subtotal = state.posCart.reduce((sum, item) => sum + item.product.price * item.quantity, 0); const discount = Math.max(0, Math.min(subtotal, Number($('#pos-discount').value || 0))); $('#pos-total').textContent = money(subtotal - discount); }
function addPosProduct(id) { const product = state.posProducts.find((item) => Number(item.id) === Number(id)); if (!product) return; const existing = state.posCart.find((item) => item.product.id === product.id); if (existing) { if (existing.quantity < product.stock) existing.quantity += 1; } else state.posCart.push({ product, quantity: 1 }); renderPosCart(); }
function printReceipt(sale) { const popup = window.open('', '_blank', 'width=480,height=700'); if (!popup) return; popup.document.write(`<html><head><title>${sale.receiptNumber}</title><style>body{font:14px Arial;padding:24px}h1{font-size:24px}hr{border:0;border-top:1px solid #999}.line{display:flex;justify-content:space-between;padding:6px 0}</style></head><body><h1>Rinova BD</h1><p>Receipt: ${escapeHtml(sale.receiptNumber)}<br>Payment: ${escapeHtml(sale.paymentMethod)}</p><hr>${state.posCart.map((item) => `<div class="line"><span>${escapeHtml(item.product.name)} × ${item.quantity}</span><strong>${money(item.product.price * item.quantity)}</strong></div>`).join('')}<hr><div class="line"><span>Subtotal</span><strong>${money(sale.subtotal)}</strong></div><div class="line"><span>Discount</span><strong>-${money(sale.discount)}</strong></div><div class="line"><strong>Total</strong><strong>${money(sale.total)}</strong></div><script>window.print()<\/script></body></html>`); popup.document.close(); }
async function completePosSale() { if (!state.posCart.length) return toast('Add a product first'); try { const data = await api('/admin/pos/sales', { method: 'POST', body: JSON.stringify({ items: state.posCart.map((item) => ({ productId: item.product.id, quantity: item.quantity })), paymentMethod: $('#pos-payment').value, discount: Number($('#pos-discount').value || 0) }) }); toast(`Sale ${data.sale.receiptNumber} completed`); printReceipt(data.sale); state.posCart = []; $('#pos-discount').value = 0; renderPosCart(); } catch (error) { toast(error.message); } }
function blogSeoValues(form) { const value = (name) => String(form.elements.namedItem(name)?.value || '').trim(); const checks = [{ label: 'Title is 15–70 characters', pass: value('title').length >= 15 && value('title').length <= 70 }, { label: 'SEO title is 30–65 characters', pass: value('seoTitle').length >= 30 && value('seoTitle').length <= 65 }, { label: 'Meta description is 70–158 characters', pass: value('metaDescription').length >= 70 && value('metaDescription').length <= 158 }, { label: 'A cover image is set', pass: /^(https:\/\/|\/assets\/|\/media\/)/i.test(value('coverImageUrl')) }, { label: 'A summary is written', pass: value('excerpt').length >= 40 }, { label: 'URL slug is short and readable', pass: /^[\p{L}\p{N}]+(?:-[\p{L}\p{N}]+)*$/u.test(value('slug')) && value('slug').length >= 3 && value('slug').length <= 70 }, { label: 'Keywords added', pass: value('keywords').split(',').map((item) => item.trim()).filter(Boolean).length >= 2 }, { label: 'Article body has real depth (300+ characters)', pass: value('body').length >= 300 }]; return { checks, score: Math.round(checks.filter((item) => item.pass).length / checks.length * 100), ready: checks.every((item) => item.pass) }; }
function updateCmsSeoReadiness() { const form = $('#cms-post-form'); if (!form) return; const seo = blogSeoValues(form); const score = $('#cms-seo-score'); if (score) { score.textContent = `${seo.score}`; score.classList.toggle('seo-ready', seo.ready); } const checklist = $('#cms-seo-checklist'); if (checklist) checklist.innerHTML = seo.checks.map((item) => `<div class="seo-check ${item.pass ? 'pass' : ''}"><span>${item.pass ? '✓' : '○'}</span>${escapeHtml(item.label)}</div>`).join(''); const seoTitle = String(form.elements.namedItem('seoTitle')?.value || '').trim() || 'Your SEO title'; const description = String(form.elements.namedItem('metaDescription')?.value || '').trim() || 'Your meta description will appear here.'; const slug = String(form.elements.namedItem('slug')?.value || '').trim() || '...'; $('#cms-google-url').textContent = `rinovabd.com/blog/${slug}`; $('#cms-google-title').textContent = seoTitle; $('#cms-google-description').textContent = description; }
function slugifyBlogTitle(value) { return String(value || '').toLowerCase().replace(/[^\p{L}\p{N}]+/gu, '-').replace(/^-+|-+$/g, '').slice(0, 70); }
async function loadMediaLibrary() { try { const data = await api('/admin/media-library'); const select = $('#cms-media-library'); if (!select) return; select.innerHTML = '<option value="">Choose an existing image</option>' + (data.media || []).map((item) => `<option value="${escapeHtml(item.url)}">${escapeHtml(item.name)} · ${escapeHtml(item.source)}</option>`).join(''); } catch (error) { toast(error.message); } }
function updateCmsCoverPreview() { const field = $('#cms-post-form')?.elements.namedItem('coverImageUrl'); const preview = $('#cms-cover-preview'); const url = String(field?.value || '').trim(); if (!preview) return; if (!url) { preview.classList.add('hidden'); preview.removeAttribute('src'); return; } preview.src = url; preview.classList.remove('hidden'); preview.onerror = () => preview.classList.add('hidden'); }
async function uploadBlogMediaDirect(file) { const form = new FormData(); form.append('file', file); const headers = state.token ? { Authorization: `Bearer ${state.token}` } : {}; const response = await fetch('/api/admin/blog-media', { method: 'POST', headers, body: form }); const data = await response.json().catch(() => ({})); if (!response.ok) throw new Error(data.error || 'Blog media upload failed.'); return data.media; }
async function uploadBlogMediaMultipart(file, onProgress) { const headers = state.token ? { Authorization: `Bearer ${state.token}` } : {}; const startResponse = await fetch('/api/admin/blog-media/multipart/start', { method: 'POST', headers: { ...headers, 'Content-Type': 'application/json' }, body: JSON.stringify({ fileName: file.name, contentType: file.type, size: file.size }) }); const start = await startResponse.json().catch(() => ({})); if (!startResponse.ok) throw new Error(start.error || 'Could not start media upload.'); const chunkSize = 8 * 1024 * 1024; const parts = []; for (let offset = 0, partNumber = 1; offset < file.size; offset += chunkSize, partNumber += 1) { const chunk = file.slice(offset, Math.min(offset + chunkSize, file.size)); const partResponse = await fetch('/api/admin/blog-media/multipart/part', { method: 'PUT', headers: { ...headers, 'Content-Type': 'application/octet-stream', 'X-Upload-Key': start.key, 'X-Upload-Id': start.uploadId, 'X-Part-Number': String(partNumber) }, body: chunk }); const part = await partResponse.json().catch(() => ({})); if (!partResponse.ok) throw new Error(part.error || `Could not upload part ${partNumber}.`); parts.push(part.part); onProgress?.(Math.min(100, Math.round((offset + chunk.size) / file.size * 100))); } const completeResponse = await fetch('/api/admin/blog-media/multipart/complete', { method: 'POST', headers: { ...headers, 'Content-Type': 'application/json', 'X-Upload-Key': start.key, 'X-Upload-Id': start.uploadId }, body: JSON.stringify({ parts, fileName: file.name, contentType: file.type }) }); const complete = await completeResponse.json().catch(() => ({})); if (!completeResponse.ok) throw new Error(complete.error || 'Could not complete media upload.'); return complete.media; }
async function uploadBlogMedia(file, onProgress) { if (!file) throw new Error('Choose an image or video file first.'); return file.size > 64 * 1024 * 1024 ? uploadBlogMediaMultipart(file, onProgress) : uploadBlogMediaDirect(file); }
async function uploadCmsMedia() { const input = $('#cms-media-file'); const file = input?.files?.[0]; const message = $('#cms-post-message'); if (!file) return toast('Choose an image or video file first.'); message.textContent = file.size > 64 * 1024 * 1024 ? 'Uploading in chunks… 0%' : 'Uploading media…'; try { const media = await uploadBlogMedia(file, (percent) => { message.textContent = `Uploading in chunks… ${percent}%`; }); $('#cms-post-form').elements.namedItem('mediaUrl').value = media.url; if (media.type === 'image' && !String($('#cms-post-form').elements.namedItem('coverImageUrl').value || '').trim()) $('#cms-post-form').elements.namedItem('coverImageUrl').value = media.url; updateCmsCoverPreview(); message.textContent = 'Media uploaded. Save the post to apply it.'; input.value = ''; updateCmsSeoReadiness(); } catch (error) { message.textContent = error.message; } }
async function uploadCmsCover() { const input = $('#cms-cover-file'); const file = input?.files?.[0]; const message = $('#cms-post-message'); if (!file) return toast('Choose a cover image first.'); message.textContent = 'Uploading cover image…'; try { const media = await uploadBlogMedia(file); if (media.type !== 'image') throw new Error('Cover image must be JPG, PNG or WEBP.'); $('#cms-post-form').elements.namedItem('coverImageUrl').value = media.url; updateCmsCoverPreview(); message.textContent = 'Cover image uploaded. Save the post to apply it.'; input.value = ''; updateCmsSeoReadiness(); } catch (error) { message.textContent = error.message; } }
function resetCmsPost() { const form = $('#cms-post-form'); if (!form) return; form.reset(); form.dataset.slug = ''; form.elements.namedItem('rights').value = 'This is hosted here. The page will claim your copyright and link to your licence.'; form.elements.namedItem('allowSearchEngines').checked = true; $('#cms-cover-preview')?.classList.add('hidden'); $('#cms-post-message').textContent = ''; updateCmsSeoReadiness(); }
function editCmsPost(slug) { const post = (state.cmsPosts || []).find((item) => item.slug === slug); if (!post) return; const form = $('#cms-post-form'); resetCmsPost(); form.dataset.slug = post.slug; for (const [key, value] of Object.entries(post)) { const field = form.elements.namedItem(key); if (field && field.type !== 'file') field.value = value ?? ''; } form.elements.namedItem('allowSearchEngines').checked = Boolean(post.allowSearchEngines); updateCmsCoverPreview(); updateCmsSeoReadiness(); form.scrollIntoView({ behavior: 'smooth', block: 'start' }); }
async function loadCms() { try { const data = await api('/admin/content'); state.cmsPosts = data.posts || []; const banner = data.content?.find((item) => item.key === 'topbar_notice'); if (banner) { const body = JSON.parse(banner.body || '{}'); $('#cms-banner-form [name="text"]').value = body.text || ''; } $('#cms-summary').innerHTML = `<div class="list-row"><span><strong>${(data.pages || []).length}</strong><small>Pages</small></span><span><strong>${(data.posts || []).length}</strong><small>Blog posts</small></span><span><strong>${(data.offers || []).length}</strong><small>Offers</small></span><span><strong>${(data.content || []).length}</strong><small>CMS blocks</small></span></div>`; $('#cms-post-list').innerHTML = (data.posts || []).map((post) => `<div class="list-row"><span><strong>${escapeHtml(post.title)}</strong><small>${escapeHtml(post.category || 'Uncategorised')} · ${escapeHtml(post.status)}</small></span><button type="button" class="icon-action" data-edit-post="${escapeHtml(post.slug)}">Edit</button></div>`).join('') || '<p class="muted">No blog posts yet.</p>'; await loadMediaLibrary(); updateCmsSeoReadiness(); } catch (error) { toast(error.message); } }
async function saveCmsBanner(event) { event.preventDefault(); try { await api('/admin/content/topbar_notice', { method: 'PUT', body: JSON.stringify({ type: 'banner', title: 'Topbar notice', body: { text: event.target.elements.text.value }, status: 'published' }) }); $('#cms-banner-message').textContent = 'Banner saved.'; } catch (error) { $('#cms-banner-message').textContent = error.message; } }
async function saveCmsPage(event) { event.preventDefault(); const values = Object.fromEntries(new FormData(event.target).entries()); try { await api('/admin/pages', { method: 'POST', body: JSON.stringify(values) }); $('#cms-page-message').textContent = 'Page saved.'; loadCms(); } catch (error) { $('#cms-page-message').textContent = error.message; } }
async function saveCmsPost(event) { event.preventDefault(); const form = event.target; const values = Object.fromEntries(new FormData(form).entries()); const action = event.submitter?.dataset.postAction || 'draft'; values.status = action === 'publish' ? 'published' : 'draft'; values.priority = Number(values.priority || 0); values.allowSearchEngines = form.elements.namedItem('allowSearchEngines').checked; values.imageUrl = values.coverImageUrl; const seo = blogSeoValues(form); if (action === 'publish' && !seo.ready) { $('#cms-post-message').textContent = 'Complete every SEO readiness item before publishing.'; updateCmsSeoReadiness(); return; } try { const data = await api('/admin/posts', { method: 'POST', body: JSON.stringify(values) }); $('#cms-post-message').textContent = action === 'publish' ? 'Post published successfully.' : 'Draft saved successfully.'; if (data.seo) updateCmsSeoReadiness(); await loadCms(); } catch (error) { $('#cms-post-message').textContent = error.message; if (error.seo) updateCmsSeoReadiness(); } }
async function saveCmsOffer(event) { event.preventDefault(); const values = Object.fromEntries(new FormData(event.target).entries()); values.discountValue = Number(values.discountValue || 0); values.minSubtotal = Number(values.minSubtotal || 0); try { await api('/admin/offers', { method: 'POST', body: JSON.stringify(values) }); $('#cms-offer-message').textContent = 'Offer saved.'; loadCms(); } catch (error) { $('#cms-offer-message').textContent = error.message; } }
function renderAdminChat() { const node = $('#admin-chat-messages'); if (!node) return; if (!state.adminChat.length) { node.innerHTML = '<div class="assistant-empty-state"><div class="assistant-empty-icon" aria-hidden="true">✦</div><strong>Good morning, Rinova.</strong><p>I can help you make a faster decision with the shop data already in your dashboard.</p><span>Try a prompt above or ask your own question below.</span></div>'; } else { node.innerHTML = state.adminChat.map((message) => `<div class="chat-message-row ${message.role}"><div class="chat-bubble ${message.role}">${escapeHtml(message.content)}</div></div>`).join(''); } node.scrollTop = node.scrollHeight; }
async function sendAdminChat(event) { event.preventDefault(); const input = $('#admin-chat-input'); const content = input.value.trim(); const status = $('#admin-chat-status'); if (!content || input.disabled) return; input.value = ''; state.adminChat.push({ role: 'user', content }); renderAdminChat(); input.disabled = true; input.setAttribute('aria-busy', 'true'); status.textContent = 'SmartGen is checking your shop data…'; try { const data = await api('/admin/chat', { method: 'POST', body: JSON.stringify({ messages: state.adminChat }) }); state.adminChat.push({ role: 'assistant', content: data.reply }); status.textContent = 'Answer ready.'; renderAdminChat(); } catch (error) { state.adminChat.push({ role: 'assistant', content: 'I could not access the shop assistant right now. Please try again.' }); status.textContent = 'SmartGen is unavailable right now.'; renderAdminChat(); } finally { input.disabled = false; input.removeAttribute('aria-busy'); input.focus(); } }
function printInvoice(orderCode) { window.open(`/invoice.html?order=${encodeURIComponent(orderCode)}`, '_blank', 'noopener'); }
const cmsPostForm = $('#cms-post-form'); cmsPostForm?.addEventListener('input', (event) => { if (event.target.name === 'title') { const slug = cmsPostForm.elements.namedItem('slug'); if (slug?.dataset.auto !== 'false') slug.value = slugifyBlogTitle(event.target.value); } if (event.target.name === 'slug') event.target.dataset.auto = 'false'; if (event.target.name === 'coverImageUrl') updateCmsCoverPreview(); updateCmsSeoReadiness(); }); cmsPostForm?.elements.namedItem('slug')?.addEventListener('focus', (event) => { if (!event.target.value) event.target.dataset.auto = 'true'; }); $('#cms-post-reset')?.addEventListener('click', resetCmsPost); $('#cms-media-library')?.addEventListener('change', (event) => { const value = event.target.value; if (value) { cmsPostForm.elements.namedItem('coverImageUrl').value = value; updateCmsCoverPreview(); updateCmsSeoReadiness(); } }); $('#cms-upload-media')?.addEventListener('click', uploadCmsMedia); $('#cms-upload-cover')?.addEventListener('click', uploadCmsCover); $('#cms-media-drop')?.addEventListener('click', (event) => { if (!event.target.closest('button') && !event.target.closest('input') && !event.target.closest('label')) $('#cms-media-file')?.click(); }); $('#cms-media-drop')?.addEventListener('dragover', (event) => { event.preventDefault(); event.currentTarget.classList.add('dragover'); }); $('#cms-media-drop')?.addEventListener('dragleave', () => $('#cms-media-drop')?.classList.remove('dragover')); $('#cms-media-drop')?.addEventListener('drop', (event) => { event.preventDefault(); $('#cms-media-drop')?.classList.remove('dragover'); const file = event.dataTransfer.files?.[0]; if (file) { const input = $('#cms-media-file'); const transfer = new DataTransfer(); transfer.items.add(file); input.files = transfer.files; uploadCmsMedia(); } }); document.addEventListener('click', (event) => { const postButton = event.target.closest('[data-edit-post]'); if (postButton) editCmsPost(postButton.dataset.editPost); }); $('#cms-media-file')?.addEventListener('change', uploadCmsMedia); $('#cms-cover-file')?.addEventListener('change', () => { if ($('#cms-cover-file').files?.[0]) uploadCmsCover(); }); updateCmsSeoReadiness(); $('#login-form').addEventListener('submit', login); $('#logout').addEventListener('click', async () => { try { await api('/admin/logout', { method: 'POST' }); } finally { state.token = ''; sessionStorage.removeItem('rinova-admin-token'); showLogin(); } }); document.querySelectorAll('.nav-item[data-view]').forEach((button) => button.addEventListener('click', () => loadView(button.dataset.view))); $('#mobile-menu').addEventListener('click', () => toggleMobileNav(!$('.sidebar').classList.contains('open'))); $('#sidebar-backdrop').addEventListener('click', closeMobileNav); $('#assistant-quick').addEventListener('click', openAssistantPopup); $('#assistant-fab').addEventListener('click', openAssistantPopup); $('#assistant-close').addEventListener('click', () => loadView('overview')); document.querySelectorAll('[data-assistant-prompt]').forEach((button) => button.addEventListener('click', () => { const input = $('#admin-chat-input'); input.value = button.dataset.assistantPrompt || ''; input.focus(); })); document.addEventListener('keydown', (event) => { if (event.key === 'Escape') { if (document.body.classList.contains('assistant-open')) loadView('overview'); else closeMobileNav(); } }); $('#morning-reset').addEventListener('click', () => { localStorage.removeItem(morningStorageKey()); renderMorningChecklist(); }); document.querySelectorAll('.period-buttons button').forEach((button) => button.addEventListener('click', () => { state.days = Number(button.dataset.days); document.querySelectorAll('.period-buttons button').forEach((item) => item.classList.toggle('active', item === button)); loadOverview(); })); document.querySelectorAll('[data-admin-mode]').forEach((button) => button.addEventListener('click', () => setAdminMode(button.dataset.adminMode))); $('#new-product').addEventListener('click', () => openProductEditor()); document.querySelectorAll('[data-close-editor]').forEach((button) => button.addEventListener('click', () => $('#product-editor').classList.add('hidden'))); $('#product-form').addEventListener('submit', saveProduct); $('#product-form [name="imageUrl"]').addEventListener('input', updateImagePreview); $('#product-form [name="mediaJson"]').addEventListener('input', renderMediaPreview); $('#upload-primary-image').addEventListener('click', uploadPrimaryImage); $('#upload-gallery-images').addEventListener('click', uploadGalleryImages); $('#product-search').addEventListener('input', loadProducts); $('#product-status').addEventListener('change', loadProducts); $('#order-search').addEventListener('input', loadOrders); $('#order-status').addEventListener('change', loadOrders); $('#return-status').addEventListener('change', loadReturns); $('#review-status').addEventListener('change', loadReviews); $('#pos-search-button').addEventListener('click', loadPosProducts); $('#pos-search').addEventListener('keydown', (event) => { if (event.key === 'Enter') { event.preventDefault(); loadPosProducts(); } }); $('#pos-clear').addEventListener('click', () => { state.posCart = []; $('#pos-discount').value = 0; renderPosCart(); }); $('#pos-discount').addEventListener('input', renderPosCart); $('#pos-complete').addEventListener('click', completePosSale); $('#barcode-label-print').addEventListener('click', printBarcodeLabels); $('#barcode-label-clear').addEventListener('click', () => { state.barcodeLabels = []; renderBarcodeLabels(); }); $('#cms-banner-form').addEventListener('submit', saveCmsBanner); $('#cms-page-form').addEventListener('submit', saveCmsPage); $('#cms-post-form').addEventListener('submit', saveCmsPost); $('#cms-offer-form').addEventListener('submit', saveCmsOffer); $('#admin-chat-form').addEventListener('submit', sendAdminChat); document.addEventListener('click', (event) => { const morningToggle = event.target.closest('[data-morning-toggle]'); if (morningToggle) toggleMorningTask(morningToggle.dataset.morningToggle); const morningView = event.target.closest('[data-morning-view]'); if (morningView) loadView(morningView.dataset.morningView); const stockButton = event.target.closest('[data-stock-id]'); if (stockButton) adjustStock(Number(stockButton.dataset.stockId), stockButton.dataset.stockName); const editButton = event.target.closest('[data-edit-id], [data-quick-edit-id]'); if (editButton) openProductEditor(state.products.find((product) => Number(product.id) === Number(editButton.dataset.editId || editButton.dataset.quickEditId))); const posAdd = event.target.closest('[data-pos-add]'); if (posAdd) addPosProduct(Number(posAdd.dataset.posAdd)); const labelAdd = event.target.closest('[data-label-add]'); if (labelAdd) addBarcodeLabel(Number(labelAdd.dataset.labelAdd)); const labelRemove = event.target.closest('[data-label-remove]'); if (labelRemove) { state.barcodeLabels = state.barcodeLabels.filter((item) => Number(item.product.id) !== Number(labelRemove.dataset.labelRemove)); renderBarcodeLabels(); } const posRemove = event.target.closest('[data-pos-remove]'); if (posRemove) { state.posCart = state.posCart.filter((item) => item.product.id !== Number(posRemove.dataset.posRemove)); renderPosCart(); } const printButton = event.target.closest('[data-print-order]'); if (printButton) printInvoice(printButton.dataset.printOrder); const approveButton = event.target.closest('[data-review-approve]'); if (approveButton) updateReview(Number(approveButton.dataset.reviewApprove), 'approved'); }); document.addEventListener('change', (event) => { const select = event.target.closest('.order-status-select'); if (select) updateOrderStatus(select.dataset.orderCode, select.value); const returnSelect = event.target.closest('.return-status-select'); if (returnSelect) updateReturn(Number(returnSelect.dataset.returnId), returnSelect.value); const labelQuantity = event.target.closest('[data-label-quantity]'); if (labelQuantity) updateBarcodeLabel(Number(labelQuantity.dataset.labelQuantity), labelQuantity.value); const reviewSelect = event.target.closest('.review-status-select'); if (reviewSelect) updateReview(Number(reviewSelect.dataset.reviewId), reviewSelect.value); }); $('#settings-form').addEventListener('submit', async (event) => { event.preventDefault(); const values = Object.fromEntries(new FormData(event.target).entries()); try { await api('/admin/settings', { method: 'PUT', body: JSON.stringify(values) }); $('#settings-message').textContent = 'Settings saved.'; toast('Store settings saved'); } catch (error) { $('#settings-message').textContent = error.message; } });
boot();
